insert into public.reviews (id, content, sort_order) values ('review-001', '{"id": "review-001", "organization": "Пермская ГРЭС", "mark": "ГРЭС", "author": "А.Л. Соколов", "role": "главный инженер Пермской ГРЭС АО «Интер РАО - Электрогенерация»", "text": "По результатам конкурсной процедуры «Приобретение и установка холодильных машин для систем кондиционирования воздуха БЩУ-1 для нужд Пермской ГРЭС «Интер РАО - Электрогенерация» подрядчиком была выбрана компания ЗАО «ИВС-Сети». В рамках проекта специалистами была произведена модернизация холодильных машин для систем кондиционирования воздуха БЩУ-1. Благодарим специалистов ЗАО «ИВС-Сети» за успешную реализацию проекта.\n\nРекомендуем компанию как надёжных партнёров, обладающих большим опытом в оказании услуг по созданию систем кондиционирования воздуха.", "logo": "/reviews/94ceda852cd027d598f5da7d33383374.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/ded/deda84bfda1cd0822b66025a388f0cde.jpg", "sortOrder": 0}'::jsonb, 0) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-002', '{"id": "review-002", "organization": "Аппарат Правительства Пермского края", "mark": "АП", "author": "В.М. Микрюков", "role": "Начальник отдела информационных ресурсов управления материально-технического обеспечения Аппарата Правительства Пермского края", "text": "В течение 2011 года компания ЗАО «ИВС-Сети» оказывала Аппарату Правительства Пермского края услугу сервиса печати. Услуга включает в себя поставку нескольких единиц оборудования в аренду — Xerox WC5225. В рамках услуги была внедрена автоматизированная система авторизации пользователей и учёта объёмов печати/копирования не только по устройствам, но и по всем сотрудникам Аппарата Правительства Пермского края. За всё это время услуга сервиса печати оказывалась на высоком уровне.\n\nПростоев оборудования и нарушения условий Государственного контракта не зафиксировано.", "logo": "/reviews/9136a2bd1d5305110fbc1ec5fed6f053.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/5be/5be85cb456de87f47013ebb96512f57b.jpg", "sortOrder": 1}'::jsonb, 1) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-003', '{"id": "review-003", "organization": "Вологдаоблкоммунэнерго", "mark": "ВКЭ", "author": "Е.А. Кринкин", "role": "заместитель директора ГЭП «Вологдаоблкоммунэнерго»", "text": "ЗАО «ИВС-Сети» является постоянным партнером ГЭП «Вологдаоблкоммунэнерго» в вопросах проектирования и внедрения современных информационных и телекоммуникационных технологий. ЗАО «ИВС-Сети» выполнены работы по проектированию, монтажу, установке и вводу в эксплуатацию корпоративной сети связи. Также выполнены работы по поставке оборудования, проектированию, монтажу и пуско-наладке системы передачи сигналов противоаварийной автоматики в систему управления турбин станции.\n\nВ целом предприятие ЗАО «ИВС-Сети» зарекомендовало себя надежным и высококвалифицированным партнером в области информационных и телекоммуникационных технологий. Персонал предприятия обладает достаточной квалификацией для выполнения работ любой сложности в области создания и обслуживания современных информационных систем.", "logo": "/reviews/33453c68c8de3aa1318051be7184c87d.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/9df/9df2cf95abcb44e714f53d5fe1ffe18b.jpg", "sortOrder": 2}'::jsonb, 2) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-004', '{"id": "review-004", "organization": "Газпром бытовые системы", "mark": "ГБС", "author": "В.Ю. Кузьминых", "role": "начальник отдела информационных технологий Чайковского филиала АО «Газпром бытовые системы»", "text": "В рамках исполнения контракта предприятием ЗАО «ИВС-Сети» было поставлено оборудование по учету продукции по штрих-кодовому обозначению в полном объеме, дополнительно были учтены пожелания Чайковского филиала АО «Газпром бытовые системы» по улучшению потребительских характеристик поставляемого товара.\n\nВыражаем благодарность специалистам предприятия ЗАО «ИВС-Сети». Рекомендуем как надежных партнеров, обладающих большим опытом в поставке оборудования.", "logo": "/reviews/2b674fc038d288f73bb5f121cd0615ab.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/416/416c1e1a03fd93ea220612e233b31117.jpg", "sortOrder": 3}'::jsonb, 3) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-005', '{"id": "review-005", "organization": "ГУ Банка России по Пермскому краю", "mark": "ЦБ", "author": "В.С. Галкин", "role": "и.о. начальника ГУ Банка России по Пермскому краю", "text": "В настоящее время ЗАО «ИВС-Сети» выполняет работы по поддержке ИТ-инфраструктуры предприятий ГУ Банка России по Пермскому краю. В рамках договора выполняются работы по техническому обслуживанию, ремонту и снабжению расходными материалами копировально-множительной техники, многофункциональных устройств и принтеров.\n\nЗа время сотрудничестве компании ЗАО «ИВС-Сети» зарекомендовала себя как надежный партнер, поставляющий качественные расходные материалы запасные части и обеспечивающий квалифицированным и оперативным сервисным обслуживанием.", "logo": "/reviews/a93503a447986d1f4b1d06258dab08c2.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/36b/36b5f65130d58de5c0a1d5b9057f1f37.jpg", "sortOrder": 4}'::jsonb, 4) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-006', '{"id": "review-006", "organization": "ИНГК-Промтех", "mark": "ИП", "author": "Т.М. Бусовикова", "role": "коммерческий директор ООО «ИНГК-ПРОМТЕХ»", "text": "По результату проведенного тендера на поставку фальцовщика «ROWE VarioFold Compact» поставщиком была выбрана компания ЗАО «ИВС-Сети». В рамках исполнения договора поставки ЗАО «ИВС-Сети» было поставлено оборудование в полном объеме и в оговоренные сроки, также проведены пуско-наладочные работы с настройкой техники и обучение нашего персонала работе с техникой. Выражаем благодарность специалистам ЗАО «ИВС-Сети».\n\nРекомендуем эту компанию как надежных партнеров, обладающих большим опытом в поставке такого оборудования.", "logo": "/reviews/2a8e3949408bf921ef2439667e4e5f4e.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/81c/81cd881c0c51ae10c18e88ad817e5c8f.jpg", "sortOrder": 5}'::jsonb, 5) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-007', '{"id": "review-007", "organization": "Лукойл-Информ", "mark": "ЛИ", "author": "И.А. Злобин", "role": "заместитель управляющего по информационным технологиям в филиале ООО «Лукойл-Информ» в Перми", "text": "Филиал ООО «Лукойл-Информ» в Перми на протяжении нескольких лет сотрудничает с предприятием ЗАО «ИВС-Сети» и пользуется его ИТ-услугами в сфере автоматизации различных направлений деятельности. Начиная с 2004 года реализован ряд проектов, направленных на повышение качества и эффективности ИТ-инфраструктуры, в том числе внедрение системы резервирования и восстановления данных.", "logo": "/reviews/faadb67ead76befc6690e9c93af3316a.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/1b3/1b3e6eb00f7f8a9f9151321eba41eecd.jpg", "sortOrder": 6}'::jsonb, 6) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-008', '{"id": "review-008", "organization": "Министерство общественной безопасности Пермского края", "mark": "МОБ", "author": "В.М. Капищенко", "role": "заместитель председателя Правительства – Министерство общественной безопасности Пермского края", "text": "Министерство общественной безопасности Пермского края выражает коллективу ЗАО «ИВС-Сети» благодарность за четкую слаженную организацию работ по государственному контракту, согласно которому на улицах Перми было установлено 83 видеокамеры системы «Безопасный город». Высокая степень организации производства и высокий технический уровень специалистов при монтаже и пуско-наладке сложного оборудования позволили получить надежную и качественную систему.", "logo": "/reviews/c22d804f0b3a37039dd5f59a8712556e.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/0ee/0ee12a3dd1b51822f8269733408c5690.jpg", "sortOrder": 7}'::jsonb, 7) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-009', '{"id": "review-009", "organization": "Министерство социального развития Пермского края", "mark": "МСР", "author": "П.С. Фокин", "role": "заместитель председателя Министерства социального развития Пермского края", "text": "Министерство социального развития Пермского края имеет положительный опыт работы с ЗАО «ИВС-Сети» в сфере автоматизации деятельности органов социальной защиты населения края, включая выполнение договорных обязательств по ряду задач.\n\nВ период 2004-2006 гг. специалистами ЗАО «ИВС-Сети» осуществлено внедрение информационно-технических решений построения ИТ-инфраструктуры для более 30 территориальных управлений Министерства социального развития Пермского края.\n\nКомпания ЗАО «ИВС-Сети» зарекомендовала себя как добросовестный исполнитель, осуществивший в требуемый срок и в полном объеме поставленные задачи в соответствии с условиями государственных контрактов.", "logo": "/reviews/bf2d266a53c9d79868d66c3ac99557d1.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/e8e/e8e306768c6952116c0d990faa4d6d86.jpg", "sortOrder": 8}'::jsonb, 8) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-010', '{"id": "review-010", "organization": "Объединенная кабельная компания", "mark": "ОКК", "author": "А.П. Бузилов", "role": "генеральный директор ООО «Объединенная кабельная компания»", "text": "ЗАО «ИВС-Сети» является постоянным партнером ООО «Объединенная кабельная компания» в вопросах проектирования и внедрения современных телекоммуникационных технологий. ЗАО «ИВС-Сети» выполнило работу по расширению телефонной сети предприятия, построенной на основе телекоммуникационных серверов AVAYA, работающих под управлением OC Linux Red Hat.\n\nВ целом ЗАО «ИВС-Сети» зарекомендовало себя надежным и высококвалифицированным партнером в области информационных и телекоммуникационных технологий. Персонал предприятия обладает достаточной квалификацией для выполнения работ любой сложности в области создания и обслуживания современных телекоммуникационных систем.", "logo": "/reviews/a40f698156c006889973558001340ebf.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/ebb/ebbf594a5414b08ca5d79522f4c2195d.jpg", "sortOrder": 9}'::jsonb, 9) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-011', '{"id": "review-011", "organization": "Уралоргсинтез", "mark": "УОС", "author": "В.Н. Попсуй", "role": "заместитель управляющего директора безопасности АО «Уралоргсинтез»", "text": "По результатам конкурсной процедуры № Т21/116 – «Выполнение 1 этапа строительно-монтажных работ по модернизации комплексной системы безопасности (видеонаблюдения) объектов основной производственной площадки АО «Уралоргсинтез» в марте 2018 года подрядчиком было выбрано ЗАО «ИВС-Сети».\n\nЦель проекта: обеспечение качественного круглосуточного наблюдения за периметром и объектами основной производственной площадки, а также круглосуточная фиксация действий в контролируемых зонах.\n\nБлагодарим специалистом ЗАО «ИВС-Сети» за качественную реализацию проекта. Рекомендуем эту компанию как надежного партнера в оказании услуг по созданию систем охранного видеонаблюдения.", "logo": "/reviews/629de22bdce2d16d842c9c00dd5d8821.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/0f7/0f771584c8b20567ad0fcb2873ac63c2.jpg", "sortOrder": 10}'::jsonb, 10) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-012', '{"id": "review-012", "organization": "Пермский завод «Машиностроитель»", "mark": "ПМ", "author": "О.Г. Фофанов", "role": "директор по ИТ-нач. УИТ АО «Пермский завод «Машиностроитель»", "text": "Компания ЗАО «ИВС-Сети» в 2015 году выполняла работы по реконструкции инженерно-технических средств физической защиты сборочно-комплектовочной базы АО «Пермский завод «Машиностроитель». Все работы ЗАО «ИВС-Сети» выполнило качественно, график выполнения работ не нарушался.", "logo": "/reviews/c0f4043584d1864cbd005986735356d0.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/08a/08adca61194316c40aa3bae9919f5688.jpg", "sortOrder": 11}'::jsonb, 11) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-013', '{"id": "review-013", "organization": "КЧХК «Уралхим»", "mark": "УХ", "author": "А.Н. Семенюк", "role": "главный инженер Филиала «КЧХК» АО « ОХК «УРАЛХИМ» в г. Кирово-Чепецке", "text": "ЗАО «ИВС-Сети» в 2015 г. выполнило проект систем пожаротушения, пожарной сигнализации, оповещения и управления эвакуацией при пожаре отделений компрессии и насосных на агрегатах АМ-70, АМ-76 цех 51.\n\nСледует отметить высокий уровень квалификации монтажного и инженерно-технического персонала ЗАО «ИВС-Сети», выполнявшего данные работы, наличие оснастки, инструмента и парка приборов для проведения работ, а также соблюдение требований нормативных документов по охране труда.", "logo": "/reviews/4cd50f2424860cfd6090402afc68f8cc.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/4ea/4ead4d559c565c9171d2b92f44fca1c0.jpg", "sortOrder": 12}'::jsonb, 12) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-014', '{"id": "review-014", "organization": "Пермский пороховой завод", "mark": "ППЗ", "author": "Г.А. Бублик", "role": "заместитель генерального директора по безопасности и режиму ФПК «Пермский пороховой завод»", "text": "ФПК «Пермский пороховой завод» выражает благодарность компании ЗАО «ИВС-Сети» за помощь в подборе и поставке многофункционального устройства XEROX AltaLink B8045. Поставка оборудования произведена в срок в полном объеме. В процессе настройки многофункционального устройства специалисты компании показали себя квалифицированными профессионалами. Рекомендуем ЗАО «ИВС-Сети» в качестве надежного партнера, обладающего большим опытом в поставке печатной техники.", "logo": "/reviews/fbf13066cbef4e37214dd80821c87a97.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/b92/b921583f6edcbb29b1d46332d4b82aad.jpg", "sortOrder": 13}'::jsonb, 13) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-015', '{"id": "review-015", "organization": "Пермский пороховой завод", "mark": "ППЗ", "author": "А.С. Мальцев", "role": "начальник отдела закупки ВМиО ФКП «Пермский пороховой завод»", "text": "По результатам конкурсной процедуры «Поставка персональных компьютеров в комплекте, тонких клиентов в комплекте, моноблоков и ноутбуков» поставщиком было выбрано ЗАО «ИВС-Сети». В рамках исполнения контракта ЗАО «ИВС-Сети» было поставлено оборудование в полном объеме и оговоренные сроки. Выражаем благодарность специалистам ЗАО «ИВС-Сети». Рекомендуем эту компанию как надежных партнеров, обладающих большим опытом в поставке компьютерного оборудования.", "logo": "/reviews/fbf13066cbef4e37214dd80821c87a97.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/3e9/3e9622d8b442f16c6dcde9ead7b5a390.jpg", "sortOrder": 14}'::jsonb, 14) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-016', '{"id": "review-016", "organization": "НИУ ВШЭ - Пермь", "mark": "ВШЭ", "author": "В.А. Матвеев", "role": "заместитель директора Пермского филиала «НИУ Высшая школа экономики»", "text": "Руководство НИУ ВШЭ-Пермь выражает благодарность и признательность ЗАО «ИВС-Сети» за профессионализм и четкость в выполнении обязательств. На протяжении длительного периода сотрудничества компания проявила себя как надежный и добросовестный партнер при осуществлении ИТ-проектов и задач, касающихся поставки сетевого, серверного оборудования, а также вычислительной техники и программного обеспечения.", "logo": "/reviews/c4c1fcd6ac546ce337f7f994255a905b.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/5d3/5d3360e6bb4832033d789084b9c887d2.jpg", "sortOrder": 15}'::jsonb, 15) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-017', '{"id": "review-017", "organization": "АКБ «Урал ФД»", "mark": "УФД", "author": "Д.В. Соромотин", "role": "начальник управления сопровождения информационных технологий ОАО АКБ «Урал ФД»", "text": "На протяжении 17 лет компания ЗАО «ИВС-Сети» является партнером нашего Банка в области информационных технологий. За прошедшее время ЗАО «ИВС-Сети» зарекомендовала себя как надежный и добросовестный поставщик вычислительной техники и программного обеспечения, своевременно и качественно исполняющий свои обязательства.\n\nСотрудники компании являются профессионалами в своей области, выполняют работу оперативно, качественно, в оговоренные сроки, поставляя нам технику и услуги, полностью отвечающие нашим требованиям.", "logo": "/reviews/a58aeb115dbced9e1b07afb7c065a2a7.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/e5b/e5b63fc9b5b11fdaad61a503105b72c3.jpg", "sortOrder": 16}'::jsonb, 16) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-018', '{"id": "review-018", "organization": "ПГМА им. Е.А. Вагнера", "mark": "ПГМА", "author": "Е.Г. Фурман", "role": "и.о. ректора, профессор ГБОУ ВПО ПГМА им. Ак. Е.А. Вагнера Минздрава России", "text": "ГБОУ ВПО ПГМА им. Ак. Е.А. Вагнера Минздрава России сотрудничает с ЗАО «ИВС-Сети» на протяжении многих лет. В рамках совместного сотрудничества за последние несколько лет было реализовано множество проектов. Одним из крупных проектов, зарекомендовавших ЗАО «ИВС-Сети» как партнера, имеющего высокую квалификацию сотрудников, стал проект по поставке и развертывании оборудования ЕМС.\n\nВ результате мы получили мощный программно-аппаратный комплект для развертывания различных задач нашего образовательного учреждения. Академия выражает компании ЗАО «ИВС-Сети» свою признательность и рекомендует ЗАО «ИВС-Сети» в качестве надежного, опытного партнера в сфере информационных технологий.", "logo": "/reviews/5689ece6ae5ac61d597aeaaf2148f689.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/002/002548bc48c0c6243102785a42e62a73.jpg", "sortOrder": 17}'::jsonb, 17) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-019', '{"id": "review-019", "organization": "ПермКапиталСтрой", "mark": "ПКС", "author": "А.В. Мехоношин", "role": "директор ООО «ПермКапиталСтрой»", "text": "ЗАО «ИВС-Сети» в 2011 году выполняла работы в качестве подрядчика ООО «ПермКапиталСтрой» по реализации строительства нового административного здания Пермского краевого суда. Проект включал комплекс работ по монтажу СКС, системы кондиционирования, серверных узлов, системы управления контроля доступом, телевизионной распределительной сети, локальной вычислительной сети, системы информационной безопасности, телефоний. В данный момент система успешно и активно эксплуатируется.\n\nЗАО «ИВС-Сети» зарекомендовала себя как надежный и высококвалифицированный партнер. Рекомендуем эту организацию для сотрудничества.", "logo": "/reviews/dd82ffd385306b233bb921a2b16d48a3.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/de4/de4cbbf1468c99e1f21612badeeb4eb9.jpg", "sortOrder": 18}'::jsonb, 18) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-020', '{"id": "review-020", "organization": "Пермская ГРЭС", "mark": "ГРЭС", "author": "А.Л. Соколов", "role": "главный инженер Филиала «Пермской ГРЭС»", "text": "По результатам конкурсной процедуры «Оснащение автоматическими установками газового пожаротушения помещений серверных зданий БЭУ-1, БЩУ-2» для филиала «Пермская ГРЭС» АО «Интер РАО – Электрогенерация» подрядчиком была выбрана группа компаний ЗАО «ИВС-Сети». Цель проекта: создание систем газового пожаротушения.\n\nВ рамках проекта специалистами ЗАО «ИВС-Сети» были проведены следующие работы: проектно-изыскательные работы, строительно-монтажные работы, пуско-наладочные работы систем пожаротушения, подготовка исполнительной документации. Благодарим специалистов ЗАО «ИВС-Сети» за успешную реализацию проекта.", "logo": "/reviews/94ceda852cd027d598f5da7d33383374.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/a9d/a9d3c3ee00982a58b8e32f72a8cebe7b.jpg", "sortOrder": 19}'::jsonb, 19) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-021', '{"id": "review-021", "organization": "Пермэнергосбыт", "mark": "ПЭС", "author": "И.В. Шершаков", "role": "генеральный директор ПАО «Пермская энергосбытовая компания»", "text": "По результатам конкурсного отбора среди крупнейших интеграторов подрядчиком было выбрано ЗАО «ИВС-Сети». Задача — перестроить техническое помещение в Центр обработки данных , оснащенный всем необходимыми инженерными системами. Для соблюдения требований безопасности и сохранения эксплуатируемого оборудования на объекте была реализована система видеонаблюдения и контроля управления доступом. В рамках этого проекта был также модернизирован ввод электропитания в здания.\n\nБлагодарим специалистов ЗАО «ИВС-Сети» за успешную реализацию проекта. Рекомендуем эту компании как надежных партнеров, обладающих большим опытом в оказании услуг по созданию Центром обработки данных.", "logo": "/reviews/3c8e58079ccd19d6518f03ef08745f7e.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/19e/19e08e9b96c06e5de2945582ec38cd46.jpg", "sortOrder": 20}'::jsonb, 20) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-022', '{"id": "review-022", "organization": "Пермская телефонная компания", "mark": "ПТК", "author": "П.В. Лисин", "role": "генеральный директор ЗАО «Пермская телефонная компания»", "text": "В течение 2012 года ЗАО «Пермская телефонная компания» привлекла ЗАО «ИВС-Сети» в качестве подрядчика для устранения возникающих аварий на действующих в г. Перми волоконно-оптических линий связи.\n\nОтмечаем, что в ходе производства и по результатам выполненных работ ЗАО «ИВС-Сети» проявило себя как надлежащая подрядная организация, способная оперативно организовать, качественно и в установленные сроки выполнить возложенные на нее объемы работ с задействованием имеющихся у нее человеческих ресурсов, технической базы и собственных ранее закупленных на свой склад материалов.\n\nНастоящим рекомендуем ЗАО «ИВС-Сети» к рассмотрению подрядной организации по строительству и по аварийно-восстановительным работам объектов волоконно-оптических линий связи.", "logo": "/reviews/8660a9a6c3a624cf04bbb15ce4a94c90.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/bac/bac9828f1141a642b699c9b8aae5af76.jpg", "sortOrder": 21}'::jsonb, 21) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-023', '{"id": "review-023", "organization": "Машиностроительное предприятие", "mark": "МП", "author": "А.Я. Сушин", "role": "заместитель управляющего директора по информационным технологиям машиностроительного предприятия", "text": "Подрядчиком для реализации проекта «Выполнение проектных строительно-монтажных и пуско-наладочных работ по переезду ЦОД было выбрано ЗАО «ИВС-Сети». Цель проекта: перенос вычислительного и коммутационного оборудования из помещения корпуса предприятия в ЦОД корпуса ИТЦ. При переезде ЦОД менее чем за сутки специалистами ЗАО «ИВС-Сети» были подготовлены, перевезены, смонтированы более 20 единиц оборудования и скоммутированы SUN-сеть и Ethernet-сеть заказчика.\n\nБлагодарим специалистов ЗАО «ИВС-Сети» за успешную реализацию проекта. Рекомендуем эту компанию как надежных партнеров, обладающих большим опытом в монтаже и пуско-наладке вычислительного и коммутационного оборудования.", "logo": null, "documentUrl": null, "sortOrder": 22}'::jsonb, 22) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-024', '{"id": "review-024", "organization": "Редуктор-ПМ", "mark": "РПМ", "author": "А.Я. Сушин", "role": "заместитель управляющего директора по информационным технологиям АО «Редуктор-ПМ»", "text": "ЗАО ЗАО «ИВС-Сети» является постоянным партнером АО «Редуктор -ПМ» в вопросах проектирования и внедрения современных телекоммуникационных технологий. ЗАО «ИВС-Сети» выполнили работу по расширению телефонной сети предприятия, построенной на основе телекоммуникационных серверов S8300D, работающих под управлением ОС Linux Red Hat. Более трех лет специалисты ЗАО «ИВС-Сети» выполняют техническое обслуживание телекоммуникационного оборудования и программного обеспечения сети телефонной связи предприятия.\n\nВ целом ЗАО «ИВС-Сети» зарекомендовало себя надежным и высококвалифицированным партнером в области информационных и телекоммуникационных технологий. Персонал предприятия обладает достаточной квалификацией для выполнения работ любой сложности в области создания и обслуживания современных информационных систем.", "logo": "/reviews/5aa5f309e672d5d24b9511fa0a7ed384.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/d48/d4879382590b4aba5c92b4abe875ee19.jpg", "sortOrder": 23}'::jsonb, 23) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-025', '{"id": "review-025", "organization": "Связьстрой", "mark": "СС", "author": "Н.В. Цветков", "role": "технический директор ООО «Связьстрой»", "text": "В течение 2012 года ООО «Связьстрой» задействовало ЗАО «ИВС-Сети» в качестве субподрядчика по строительству фрагмента сети широкополосного доступа по технологии FTTB в г. Березники Пермского края для ЗАО «Урал-ТрансТелеКом».\n\nОтмечаем, что в ходе производства и по результатам выполненных работ ЗАО «ИВС-Сети» проявило себя как надлежащая подрядная организация, способная оперативно организовать, качественно и в установленные сроки выполнить возложенные на нее объемы работ с задействованием имеющихся у нее человеческих ресурсов, технической базы и собственных ранее закупленных материалов.\n\nНастоящим рекомендуем ЗАО «ИВС-Сети» к рассмотрению в качестве подрядной организации по строительству объектов волоконно-оптических линий связи.", "logo": "/reviews/a895cf145d295e596e23cec5836b2394.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/92a/92aced453368d9d9508ba67ec09e7b13.jpg", "sortOrder": 24}'::jsonb, 24) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-026', '{"id": "review-026", "organization": "Соликамский магниевый завод", "mark": "СМЗ", "author": "А.В. Прокопенко", "role": "генеральный директор ОАО «Соликамский магниевый завод»", "text": "ОАО «Соликамский магниевый завод» на протяжении нескольких лет сотрудничает с компанией ЗАО «ИВС-Сети» в области информационных технологий. За это время ЗАО «ИВС-Сети» зарекомендовала себя как надежный грамотный партнер, способный решать задачи любой сложности, такие как поставки вычислительной техники, создание современных серверных решений, развертывание сетей любой конфигурации, установка и настройка общесистемного и прикладного программного обеспечения.", "logo": "/reviews/6545d99856e28fed288fa837292eaef1.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/267/26777545959502c367142b986dc169fb.jpg", "sortOrder": 25}'::jsonb, 25) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-027', '{"id": "review-027", "organization": "Стратегические бизнес-системы", "mark": "СБС", "author": "А.Н. Носков", "role": "заместитель генерального директора по Пермском у краю и Республике Коми, директор филиала в г. Перми ООО «Стратегические бизнес-системы»", "text": "В течение 2012 года ООО «Стратегические бизнес-системы» задействовало ЗАО «ИВС-Сети» в качестве субподрядчика по строительству волоконно-оптических линий сети для объектов КЭС-Холдинга на территории Пермского края.\n\nОтмечаем, что в ходе производства и по результатам выполненных работ ЗАО «ИВС-Сети» проявило себя как добросовестная подрядная организация, способная оперативно организовать, качественно и в установленные сроки выполнить возложенные на нее объемы работ с задействованием имеющихся у нее человеческих ресурсов, технической базы и собственных ранее закупленных материалов.\n\nНастоящим рекомендуем ЗАО «ИВС-Сети» к рассмотрению в качестве подрядной организации по строительству объектов волоконно-оптических линий связи.", "logo": "/reviews/8eb6bac15e6c3b35be151470e0465dcb.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/6f7/6f738f7a115186701682bf91d755da5e.jpg", "sortOrder": 26}'::jsonb, 26) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-028', '{"id": "review-028", "organization": "СтройПанельКомплект", "mark": "СПК", "author": "А.В. Сыропятов", "role": "главный инженер ОАО «СтройПанельКомплект»", "text": "ЗАО «ИВС-Сети» является постоянным партнером ОАО «СтройПанельКомплект» в вопросах проектирования и внедрения современных телекоммуникационных технологий. ЗАО «ИВС-Сети» выполнили работу по проектированию, монтажу, установке и вводу в эксплуатацию коммуникационной платформы AVAYA на основе телекоммуникационного сервера S8400, работающего под управлением ОС Linux Red Hat. Специалистами ЗАО «ИВС-Сети» выполнен проект на подключение телефонной сети предприятия в телефонной сети общего пользования г. Перми.\n\nЗАО «ИВС-Сети» зарекомендовало себя надежным и высококвалифицированным партнером в области информационных и телекоммуникационных технологий. Персонал предприятия обладает достаточной квалификацией для выполнения работ любой сложности в области создания и обслуживания современных информационных систем. Рекомендуем ЗАО «ИВС-Сети» в качестве системного интегратора по построению и модернизации сетей связи на базе телекоммуникационных серверов AVAYA.", "logo": "/reviews/16b54a94e6fbed2f6583dce4b8bf9fb9.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/795/79551d12bcb9f803e16e17a4362ed2ac.jpg", "sortOrder": 27}'::jsonb, 27) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-029', '{"id": "review-029", "organization": "Уралкалий", "mark": "УК", "author": "А.Н. Тодосиенко", "role": "заместитель начальника управления информационных технологий ОАО «Уралкалий»", "text": "ОАО «Уралкалий» в течение нескольких лет активно сотрудничает с предприятием ЗАО «ИВС-Сети», совместно с которым были реализован ряд проектов по развитию ИТ-инфраструктуры: в частности, проектирование, построение и модернизация СЕС, внедрение систем персональной и групповой работы, поставка и обслуживание средств вычислительной и множительной техники. Все проекты были выполнеы в сроки, оговоренные в контрактах. Качество выполнения работ — высокое, замечаний и претензий нет.", "logo": "/reviews/9fd12549432c3ca22656f6180597115b.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/c08/c089e3fc2ef359e7734a02d219a82607.jpg", "sortOrder": 28}'::jsonb, 28) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-030', '{"id": "review-030", "organization": "Уралкалий", "mark": "УК", "author": "А.Н. Тодосиенко", "role": "начальник отдела связи центра информационных технологий ОАО «Уралкалий»", "text": "В 2005 г. компания ЗАО «ИВС-Сети» в качестве генподрядчика выполнила работы по проектированию и строительству Центра обработки данных на территории ОАО «Уралкалий». В ходе проведения работ компания проявила высокую ответственность за выполненные работы, глубокий анализ потребностей заказчика в ходе реализации проекта. За время сотрудничества мы убедились в высоком профессионализме ее сотрудников.\n\nЗа период совместной работы ЗАО «ИВС-Сети» зарекомендовала себя как надежный и высококвалифицированный партнер, обеспечивающий высокое качество и плановые сроки выполнения работ. ОАО «Уралкалий» рекомендует компанию ЗАО «ИВС-Сети» как надежного и проверенного партнера и намеревается и впредь сотрудничать с этой компанией.", "logo": "/reviews/9fd12549432c3ca22656f6180597115b.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/090/0902dd1ac36879a3878680e61f48d0bd.jpg", "sortOrder": 29}'::jsonb, 29) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-031', '{"id": "review-031", "organization": "Уралтеханалит", "mark": "УТА", "author": "А.Н. Лупский", "role": "директор ООО «Уралтеханалит»", "text": "ЗАО «ИВС-Сети» осуществляет комплексное обслуживание ИТ-инфраструктуры ООО «Уралтеханалит», выключающее поставки электронно-вычислительной техники, расходных материалов, запасных частей, обеспечение оперативным сервисным обслуживанием. За годы сотрудничества компания всегда качественно, в срок и на высоком профессиональном уровне исполняла взятые на себя договорные обязательства.", "logo": "/reviews/12165b7adf0c10a9bdeb7ad9b3300160.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/959/959d4311fa9e86462d6b9a003641c6ef.jpg", "sortOrder": 30}'::jsonb, 30) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-032', '{"id": "review-032", "organization": "Филиал «Азот» ОХК «Уралхим»", "mark": "АЗОТ", "author": "А.Г. Щукин", "role": "заместитель руководителя службы ИТ, Филиал «Азот» ОАО «ОХК «УРАЛХИМ» в городе Березники", "text": "Выражаем благодарность ЗАО «ИВС-Сети» за качественно выполненную работу по проектированию и строительству ЦОД Филиала «Азот» ОАО «ОХК «УРАЛХИМ». Компания профессионально, ответственно и грамотно организовала процесс работы. Специалисты компании продемонстрировали высокую степень квалификации, тем самым зарекомендовав себя и компанию как надежного партнера в области информационных технологий, обеспечивающего высокое качество выполненных работ.\n\nРекомендуем компанию ЗАО «ИВС-Сети» как проверенного и надежного партнера.", "logo": "/reviews/4cd50f2424860cfd6090402afc68f8cc.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/dd4/dd4ac6c4aec948864293c07356cfbe8c.jpg", "sortOrder": 31}'::jsonb, 31) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-033', '{"id": "review-033", "organization": "ВНИПИнефть", "mark": "ВН", "author": "Филиал ВНИПИнефть в г. Перми", "role": "Заместитель технического директора по ИТ", "text": "Хочется отметить успешную работу ЗАО «ИВС-Сети». Сотрудники компании являются профессионалами, выполняют работу оперативно, качественно, в оговоренные сроки. В течение 2010 года ЗАО «ИВС-Сети» поставило на предприятие копировальное оборудование и многофункциональное устройство Xerox. За время совместного сотрудничества не было никаких нареканий по поводу поставляемой продукции. Будем рады дальнейшему выгодному сотрудничеству с ЗАО «ИВС-Сети».", "logo": "/reviews/4bb8cfd9a02021f86f79be521b0af27b.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/9bf/9bfcbadfc72ed1133bc8eca156005292.jpg", "sortOrder": 32}'::jsonb, 32) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-034', '{"id": "review-034", "organization": "ФСБ, войсковая часть 2122", "mark": "ФСБ", "author": "В.А. Меркурьев", "role": "командир войсковой части 2122, полковник, Федеральная служба безопасности, г. Сочи", "text": "Предприятием ЗАО «ИВС-Сети» был произведен большой объем работы по оборудованию пограничных объектов техническими средствами, что благотворно повлияло на надежной охраны южных рубежей нашей Родины. Сотрудники группы компании «ИВС» при выполнении работ проявили высокий профессионализм, старание и ответственность за порученное дело. Выражаю коллективу компании, принявшему участие в оборудовании объектов нашей части, искреннюю благодарность и надеюсь на наше дальнейшее плодотворное и деловое сотрудничество.", "logo": "/reviews/04abbbc8bc5c9834ef18e0c1c72aab55.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/0c3/0c341c3c0a7c4ce6be7fc1d4c5d3c85c.jpg", "sortOrder": 33}'::jsonb, 33) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-035', '{"id": "review-035", "organization": "Уралкалий", "mark": "УК", "author": "О.В. Пеньков", "role": "начальник управления информационных систем ПАО «Уралкалий»", "text": "В 2017 году руководством компании принято решение о создании Объединенного центра обслуживания «Уралкалий» и внедрении «Системы управления электронным бухгалтерским документооборотом». По результатам тендера подрядчиком была выбрана группа компаний ЗАО «ИВС-Сети».\n\nЦель проекта: организация юридически значимого электронного документооборота, охватывающего все организационные единицы, которые обрабатывают финансовые документы.\n\nВ рамках проекта специалистами ЗАО «ИВС-Сети» были проведены следующие работы: обследование бизнес-процесса предприятия, выбор оптимального способа выполнения задач и достижения целей проекта, разработка технического задания, выбор оборудования для реализации проекта, доработка 1С: ERP, разработка инструкций для пользователей, обучение пользователей и специалистов поддержки Заказчика.\n\nБлагодарим специалистов ООО «ИВС» за успешную реализацию проекта. Рекомендуем данную кампанию как надежных партнеров, обладающих большим опытом в оказании услуг по автоматизации процессов на базе продуктов 1С.", "logo": "/reviews/9fd12549432c3ca22656f6180597115b.jpg", "documentUrl": null, "sortOrder": 34}'::jsonb, 34) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-036', '{"id": "review-036", "organization": "Камский кабель", "mark": "КК", "author": "В.Е. Молоковских", "role": "генеральный директор ООО «Камский кабель»", "text": "В 2013 году в ООО «Камский кабель» возникла необходимость в автоматизации процесса документооборота. Для выполнения этих задач ООО «Камский кабель» обратилось в ГК «ИВС». Компания «ИВС» выполнила работы по автоматизации процессов на платформе программного обеспечения DIRECTUM. Внедрение системы электронного документооборота DIRECTUM позволило повысить эффективность бизнес-процессов компании. За время работы ЗАО «ИВС» зарекомендовала себя как грамотный и надежный партнер.\n\nСотрудники проявили высокий профессионализм и ответственность.", "logo": "/reviews/649cfcc267ff67e1cf99916f567f0254.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/051/051126a2171318eec57d079160e0609d.PNG", "sortOrder": 35}'::jsonb, 35) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-037', '{"id": "review-037", "organization": "МКУ «Информационные технологии»", "mark": "МКУ", "author": "А.Ю. Митрофанов МКУ ИТ", "role": "Директор", "text": "С 2019 года МКУ «Информационные технологии» пользуется услугами, которые предоставляет компания ЗАО «ИВС-СЕТИ» по обеспечению бесперебойной работы копировально-множительной техники, систем бесперебойного питания, компьютерной техники и сопутствующих периферийных устройств.\n\nЗа период сотрудничества можно отметить высокую квалификацию инженерного персонала и сотрудников административно-оперативного сопровождения. Работы производятся в срок и надлежащего качества. Всё оборудование работает эффективно и бесперебойно в соответствии с SLA.\n\nНаличие собственной материально-технической базы, отвечающей требуемым условиям рынка, позволяет компании оказывать услуги на должном уровне.\n\nБлагодарим за сотрудничество и выражаем намерение и далее пользоваться услугами компании ЗАО «ИВС-СЕТИ».\n\nДиректор А.Ю. Митрофанов", "logo": null, "documentUrl": null, "sortOrder": 36}'::jsonb, 36) on conflict (id) do nothing;
insert into public.reviews (id, content, sort_order) values ('review-038', '{"id": "review-038", "organization": "Уралкалий", "mark": "УК", "author": "А.А Рюмкин", "role": "Главный энергетик - начальник управления главного энергетика ПАО \"Уралкалий\"", "text": "Компания ЗАО «ИВС-СЕТИ» в период с 2021 года по настоящее время обеспечивает комплексное регламентное обслуживание и выполнение внеплановых и восстановительных работ дизель-генераторных установок в ПАО «Уралкалий». Перечень оборудования включает в себя 28 установок разной мощности и исполнения.\n\nВысокая степень организации производства работ и соблюдение требований нормативно-технической документации и стандартов позволяет получить оперативную, надежную и качественную систему поддержки работоспособности оборудования.\n\nСледует отметить высокий уровень квалификации инженерно-технического персонала ЗАО «ИВС-Сети», выполняющего данные работы, наличие оснастки, инструмента и парка приборов для проведения работ, а также соблюдение требований нормативных документов по охране труда.\n\nРекомендуем как надежных партнеров, обладающих большим опытом в сфере технического обслуживания и ремонта сложного энергетического оборудования.", "logo": "/reviews/9fd12549432c3ca22656f6180597115b.jpg", "documentUrl": "https://ivs-corp.ru/upload/iblock/c85/f8iljpjuw867cq4vlffdfl1qr2hjtvzf.pdf", "sortOrder": 37}'::jsonb, 37) on conflict (id) do nothing;
insert into public.vacancies (id, content, sort_order) values ('vacancy-001', '{"id": "vacancy-001", "title": "Программист 1С", "city": "Пермь", "phone": "+7 (342) 238-52-84", "email": "job@ivs-corp.ru", "summary": ["Требуемый опыт работы: 1–3 года", "Полная занятость, полный день"], "sections": [{"title": "Обязанности", "items": ["Внедрение информационных систем на базе программных продуктов «1С:Предприятие 8»;", "Написание отчетов, обработок;", "Участие в разработке технических заданий на информационные системы;", "Консультативная и техническая поддержка пользователей;", "Обновление конфигурации в соответствии с изменениями в законодательстве;", "Интеграция с другими информационными системами."]}, {"title": "Требования", "items": ["Высшее образование;", "Опыт работы с конфигурациями «1С: Предприятие 8» (УПП, Бухгалтерия, Зарплата);", "Желательно наличие сертификатов – «1С: Профессионал 8», «1С: Специалист 8»."]}, {"title": "Условия", "items": ["Официальное трудоустройство (трудовой договор);", "Работа в офисе и у заказчика;", "5 дневная рабочая неделя;", "Режим работы с 9.00 до 18.00;", "Обучение, повышение квалификации, карьерный рост;", "Заработная плата обсуждается с кандидатом, прошедшим собеседование."]}], "sortOrder": 0}'::jsonb, 0) on conflict (id) do nothing;
insert into public.vacancies (id, content, sort_order) values ('vacancy-002', '{"id": "vacancy-002", "title": "Системный администратор", "city": "Пермь", "phone": "+7 (342) 238-52-84", "email": "job@ivs-corp.ru", "summary": ["Требуемый опыт работы: 1–3 года", "Полная занятость, полный день"], "sections": [{"title": "Обязанности", "items": ["Администрирование серверов на базе ОС: Linux, Windows;", "Администрирование виртуальной инфраструктуры на базе Hyper-V, VMware;", "Администрирование базовых сетевых служб и сервисов;", "Консультирование пользователей;", "Ведение рабочей документации;", "Выполнение заявок в ITSM-системе."]}, {"title": "Требования", "items": ["Опыт работы с IT сфере - более 2 лет;", "Наличие сертификатов Microsoft, Cisco, Huawei - приветствуется;", "Знание платформ виртуализации под Linux - приветствуется;", "Образование - не ниже среднего профессионального;", "Знание технического английского."]}, {"title": "Условия", "items": ["Работа в офисе."]}, {"title": "Ключевые навыки", "items": ["Английский — A1 — Начальный;", "Linux;", "Английский язык;", "MS Office;", "Microsoft Access."]}], "sortOrder": 1}'::jsonb, 1) on conflict (id) do nothing;
insert into public.vacancies (id, content, sort_order) values ('vacancy-003', '{"id": "vacancy-003", "title": "Электромонтер линейных сооружений связи", "city": "Пермь", "phone": "+7 (342) 238-52-84", "email": "job@ivs-corp.ru", "summary": ["Требуемый опыт работы: 1–3 года", "Полная занятость, полный день"], "sections": [{"title": "Обязанности", "items": ["Монтажные работы вновь строящихся сетей (систем);", "Обслуживание сетей;", "Аварийно-восстановительные работы линейных сооружений телефонной связи, радиофикации, громкоговорящей связи и абонентских устройств этих систем, локальной системы оповещения, охранно-пожарной сигнализации, систем видеонаблюдения, СКУД, сети передачи данных и структурированной кабельной сети;", "Работы выполняются в соответствии с требованиями ПТЭЭП, ПОТЭУ, разработанными инструкциями по эксплуатации оборудования, нормативными документами по сфере деятельности с соблюдением требований по охране труда и промышленной безопасности."]}, {"title": "Требования", "items": ["Знания технологий монтажа кроссового и оконечного оборудования систем связи, радиофикации, громкоговорящей связи, локальной системы оповещения, охранно-пожарной сигнализации, систем видеонаблюдения, СКУД, сети передачи данных;", "Владение навыками способов прокладки кабельной продукции линейных сооружений, структурированной кабельной сети, слаботочных сетей;", "Умение ремонтировать абонентские устройства систем телефонной связи с использованием типовых элементов замены."]}, {"title": "Условия", "items": ["Трудовой договор.", "Работа на территории Заказчика."]}], "sortOrder": 2}'::jsonb, 2) on conflict (id) do nothing;
