-- Контент разделов компании. Записи используют одну модель в витрине и админке.
create table if not exists public.reviews (
 id text primary key,
 content jsonb not null,
 sort_order integer not null default 0,
 is_published boolean not null default true,
 constraint reviews_content_id check (content->>'id' = id)
);
alter table public.reviews enable row level security;
drop policy if exists "Published content" on public.reviews;
create policy "Published content" on public.reviews for select to anon, authenticated using (is_published);
grant select on public.reviews to anon, authenticated;
-- Запись выполняет сервер админки с service_role, ключ не передаётся браузеру.
create table if not exists public.vacancies (
 id text primary key,
 content jsonb not null,
 sort_order integer not null default 0,
 is_published boolean not null default true,
 constraint vacancies_content_id check (content->>'id' = id)
);
alter table public.vacancies enable row level security;
drop policy if exists "Published content" on public.vacancies;
create policy "Published content" on public.vacancies for select to anon, authenticated using (is_published);
grant select on public.vacancies to anon, authenticated;
-- Запись выполняет сервер админки с service_role, ключ не передаётся браузеру.
